const raw = $input.first().json.data || $input.first().json.body || $input.first().json || '';
const rawText = typeof raw === 'string' ? raw : JSON.stringify(raw);

const items = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;
while ((match = itemRegex.exec(rawText)) !== null) {
  const block = match[1];
  const titleRaw = (block.match(/<title>([\s\S]*?)<\/title>/) || [])[1] || '';
  const linkRaw = (block.match(/<link>([\s\S]*?)<\/link>/) || [])[1] || '';
  const pubDateRaw = (block.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || [])[1] || '';

  const clean = (s) => s.replace(/<!\[CDATA\[|\]\]>/g, '').trim();
  const title = clean(titleRaw);
  const link = clean(linkRaw);
  let publishedAt = null;
  try { publishedAt = pubDateRaw ? new Date(pubDateRaw).toISOString() : null; } catch (e) { publishedAt = null; }

  if (title && link) {
    items.push({ title, link, source: 'CoinTelegraph', published_at: publishedAt });
  }
}

return items.slice(0, 20).map(i => ({ json: i }));

